import asyncio
import signal
from collections.abc import Awaitable, Callable


async def run_tasks(
    tasks: list[Callable[[], Awaitable[None]]], max_concurrent: int
) -> None:
    semaphore = asyncio.Semaphore(max_concurrent)
    running = set[asyncio.Task[None]]()

    async def worker(task_fn: Callable[[], Awaitable[None]]) -> None:
        async with semaphore:
            await task_fn()

    loop = asyncio.get_running_loop()
    stop_event = asyncio.Event()

    def _on_signal() -> None:
        stop_event.set()
        for t in running:
            t.cancel()

    loop.add_signal_handler(signal.SIGINT, _on_signal)
    loop.add_signal_handler(signal.SIGTERM, _on_signal)

    try:
        for task_fn in tasks:
            if stop_event.is_set():
                break
            t = asyncio.create_task(worker(task_fn))
            running.add(t)
            t.add_done_callback(running.discard)

        if running:
            await asyncio.wait(
                running, return_when=asyncio.FIRST_COMPLETED
            )
    finally:
        # cancel any signal handlers we installed
        try:
            loop.remove_signal_handler(signal.SIGINT)
        except (NotImplementedError, ValueError):
            pass
        try:
            loop.remove_signal_handler(signal.SIGTERM)
        except (NotImplementedError, ValueError):
            pass

        # drain remaining tasks (cleanup) with a timeout
        if running:
            _, pending = await asyncio.wait(
                running, timeout=30, return_when=asyncio.ALL_COMPLETED
            )
            for t in pending:
                t.cancel()

